package provider

import (
	"fmt"
	"testing"

	"github.com/hashicorp/terraform-plugin-testing/helper/resource"
	"github.com/hashicorp/terraform-plugin-testing/terraform"
)

func TestAccDataSource_SCIM_Group(t *testing.T) {
	name := "scim_test"
	idpID := "tf-basic-scim-group"
	config := func(idpID string) string {
		return fmt.Sprintf(`
provider "temporalcloud" {
}

data "temporalcloud_scim_group" "terraform" {
	idp_id = "%s"
}
output "scim_group" {
	value = data.temporalcloud_scim_group.terraform
}
	`, idpID)
	}

	resource.Test(t, resource.TestCase{
		PreCheck: func() {
			testAccPreCheck(t)
		},
		ProtoV6ProviderFactories: testAccProtoV6ProviderFactories,
		Steps: []resource.TestStep{
			{
				Config: config(idpID),
				Check: func(s *terraform.State) error {

					output, ok := s.RootModule().Outputs["scim_group"]
					if !ok {
						return fmt.Errorf("missing expected output")
					}
					outputValue, ok := output.Value.(map[string]interface{})
					if !ok {
						return fmt.Errorf("expected value to be map")
					}
					outputName, ok := outputValue["name"].(string)
					if !ok {
						return fmt.Errorf("expected value to be a string")
					}
					if outputName != name {
						return fmt.Errorf("expected scim group name to be: %s, got: %s", name, outputName)
					}
					return nil
				},
			},
		},
	})
}

package validation

import (
	"context"
	"testing"

	"github.com/hashicorp/terraform-plugin-framework/attr"
	"github.com/hashicorp/terraform-plugin-framework/path"
	"github.com/hashicorp/terraform-plugin-framework/resource/schema"
	"github.com/hashicorp/terraform-plugin-framework/schema/validator"
	"github.com/hashicorp/terraform-plugin-framework/tfsdk"
	"github.com/hashicorp/terraform-plugin-framework/types"
	internaltypes "github.com/temporalio/terraform-provider-temporalcloud/internal/types"
)

func TestSetMustBeEmptyWhen(t *testing.T) {
	tests := []struct {
		name           string
		otherPath      path.Path
		values         []string
		setValue       types.Set
		otherValue     internaltypes.CaseInsensitiveStringValue
		expectedErrors bool
	}{
		{
			name:           "empty set when other value matches",
			otherPath:      path.Root("other"),
			values:         []string{"test"},
			setValue:       types.SetValueMust(types.StringType, []attr.Value{}),
			otherValue:     internaltypes.CaseInsensitiveString("test"),
			expectedErrors: false,
		},
		{
			name:      "non-empty set when other value matches",
			otherPath: path.Root("other"),
			values:    []string{"test"},
			setValue: types.SetValueMust(types.StringType, []attr.Value{
				types.StringValue("value1"),
			}),
			otherValue:     internaltypes.CaseInsensitiveString("test"),
			expectedErrors: true,
		},
		{
			name:      "non-empty set when other value doesn't match",
			otherPath: path.Root("other"),
			values:    []string{"test"},
			setValue: types.SetValueMust(types.StringType, []attr.Value{
				types.StringValue("value1"),
			}),
			otherValue:     internaltypes.CaseInsensitiveString("other"),
			expectedErrors: false,
		},
		{
			name:      "case insensitive matching",
			otherPath: path.Root("other"),
			values:    []string{"TEST"},
			setValue: types.SetValueMust(types.StringType, []attr.Value{
				types.StringValue("value1"),
			}),
			otherValue:     internaltypes.CaseInsensitiveString("test"),
			expectedErrors: true,
		},
		{
			name:           "null set value",
			otherPath:      path.Root("other"),
			values:         []string{"test"},
			setValue:       types.SetNull(types.StringType),
			otherValue:     internaltypes.CaseInsensitiveString("test"),
			expectedErrors: false,
		},
		{
			name:           "unknown set value",
			otherPath:      path.Root("other"),
			values:         []string{"test"},
			setValue:       types.SetUnknown(types.StringType),
			otherValue:     internaltypes.CaseInsensitiveString("test"),
			expectedErrors: false,
		},
		{
			name:      "null other value",
			otherPath: path.Root("other"),
			values:    []string{"test"},
			setValue: types.SetValueMust(types.StringType, []attr.Value{
				types.StringValue("value1"),
			}),
			otherValue: internaltypes.CaseInsensitiveStringValue{
				StringValue: types.StringNull(),
			},
			expectedErrors: false,
		},
		{
			name:      "unknown other value",
			otherPath: path.Root("other"),
			values:    []string{"test"},
			setValue: types.SetValueMust(types.StringType, []attr.Value{
				types.StringValue("value1"),
			}),
			otherValue: internaltypes.CaseInsensitiveStringValue{
				StringValue: types.StringUnknown(),
			},
			expectedErrors: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// Create a schema with the validator
			s := schema.Schema{
				Attributes: map[string]schema.Attribute{
					"test": schema.SetAttribute{
						ElementType: types.StringType,
						Required:    true,
						Validators: []validator.Set{
							SetMustBeEmptyWhen(tt.otherPath, tt.values),
						},
					},
					"other": schema.StringAttribute{
						Required:   true,
						CustomType: internaltypes.CaseInsensitiveStringType{},
					},
				},
			}

			// Create the config values
			configVal := map[string]attr.Value{
				"test":  tt.setValue,
				"other": tt.otherValue,
			}

			// Create the config object
			configObj, diags := types.ObjectValue(map[string]attr.Type{
